import { expect, expectStatus, test } from "../../fixtures";

test("Approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs, factory }) => {
  // Arrange
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview();

  // Act
  for (const extraction of Object.values(extractions)) {
    const response = await reviewer.post(`/api/extractions/${extraction.id}/decision`, {
      data: { decision: "approve" },
    });
    await expectStatus(response, 200);
  }

  // Assert
  // Approval is applied in the background, so poll until the vendor status settles.
  await expect
    .poll(async () => {
      const current = await expectStatus<{ status: string }>(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
      return current.status;
    }, { message: "vendor is approved once every extraction is approved" })
    .toBe("approved");

  await expect
    .poll(async () => {
      const trail = await expectStatus<{ items: { action: string }[] }>(
        await reviewer.get(`/api/vendors/${vendor.id}/audit`),
        200,
      );
      return trail.items.map((event) => event.action);
    }, { message: "audit trail records vendor.approved" })
    .toContain("vendor.approved");
});
